import {formatCode} from "../../components/TreeViewContainer/utils.TreeView";

const traverseTree = (treeArr, callback, arr) => {
    if (!treeArr) return null
    treeArr.forEach(node => {
        callback(node, arr);
        if (node.children && node.children.length > 0) {
            traverseTree(node.children, callback);
        }
    });
};

const deleteNode = (nodes, id) => {

    nodes.forEach((node, index) => {
        if (node.id === id) {
            nodes.splice(index, 1);
            return true;
        }
        if (node.hasOwnProperty("data")) return
        if (node.children.length > 0) {
            const del = deleteNode(node.children, id);
            if (del) {
                return true
            }
        }
    })
    return false
}
const findNodeById = (nodes, id) => {
    let foundNode = null;
    traverseTree(nodes, node => {
        if (node.id === id) {
            foundNode = node;
        }
    });
    return foundNode;
};

const findNodeByCode = (nodes, code) => {
    let foundNode = null;
    traverseTree(nodes, node => {
        if (node?.data?.code === code) {
            foundNode = node;
        }
    })
    return foundNode;
}

const getPredicate = (argsObj) => {
    if (Object.keys(argsObj).length === 0) {
        return "";
    }
    const {filterStr, filterKey} = argsObj;
    const substrings = filterStr.trim().toLowerCase().split(" ");

    switch (filterKey){
        case "OR":
            return (node) => node.data && substrings.some(substring=> node.name.toLowerCase().includes(substring));
        case "AND":
            const regexp = new RegExp(substrings.map(i => `(?=.*${i})`).join(""), "gi");
            return (node) => node.data && regexp.test(node.name.toLowerCase());
        default:
            return ""
    }
}

function filterTree(obj, cb) {

    if (cb(obj)) {
        return {...obj};
    } else if (obj.children) {
        let result = obj.children
            .map(child => filterTree(child, cb))
            .filter(Boolean);
        if (result.length) {
            return {...obj, children: result};
        }
    }
    return null;
}

const buildTreeArr = (dataArr, filterObj) => {
    if (!dataArr || dataArr?.length === 0) return null;
    const map = {};
    let resultTree = {name: "root", id: 0, parent: null, children: []}

    dataArr.forEach(item => {
        if (item.data) {
            map[item.id] = item
        } else {
            map[item.id] = {...item, children: []}
        }

    })
    dataArr.forEach(item => {
        if (item.parent === 0) {
            resultTree.children.push(map[item.id])
        } else if (map[item.parent]) {
            map[item.parent].children.push(map[item.id])
        }
    })

    if (Object.keys(filterObj).length) {
        return filterTree(resultTree, getPredicate(filterObj));
    }

    return resultTree;
}

const extractTextBetweenBrackets = (text) => {
    const match = text.match(/\{(.*?)\}/);
    return match ? `{${match[1]}}` : null;
}

const transformTextOrderToObj = (text) => {
    const orderJson = JSON.parse(extractTextBetweenBrackets(text));

    if (!orderJson || orderJson?.length === 0) return [];
    const {headers, values} = orderJson;
    const result = [];
    values.forEach((value) => {
        const obj = {}
        headers.forEach((key, index) => {
            if (key === "code") {
                obj["code"] = formatCode(value[index])
            } else {
                obj[key] = value[index]
            }
        })
        result.push(obj)
    })
    return result

}
const transformDataByFields = (arr, fields) => {

    return arr.map(item => {
        const resultItem = {};
        fields.forEach(field => {
            resultItem[field] = item?.data[field];
        });
        return resultItem;
    });
}

const addLocalStorageDataToTree = (tree, lsCart, fields) => {
    const treeArr = tree?.children;
    const additionalData = transformDataByFields(lsCart, fields);
    additionalData.forEach(item => {
        addHighLightlDataToTreeArr(item, treeArr);
    });
    return tree;
}


const addHighLightlDataToTreeArr = (item, treeArr) => {
    const searchCode = item.code;
    const index = 2; // текущий заказ - 2, история -1, в резерве - 0
    const foundNode = findNodeByCode(treeArr, searchCode);
    if (foundNode) {
        foundNode.data = {...foundNode.data, ...item};
        highlightParent(foundNode, (parentNode) => {
            parentNode.highlightArr[index] += 1;
        }, treeArr);
    }
}

const getValueLocalStorage = (key) => {
    try {
        const serializedState = localStorage.getItem(key);
        return serializedState ? JSON.parse(serializedState) : null;
    } catch (err) {
        console.log(err.message);
        return null;
    }
}
const addQuantityToTree = (tree, itemId, quantity) => {
    const treeArr = tree?.children;
    const foundNode = findNodeById(treeArr, itemId);
    if (foundNode) {
        const index = 2;
//        if (quantity > 0) {
        if (quantity > 0 && !Boolean(foundNode?.data?.quantity)) {
            highlightParent(foundNode, (parentNode) => {
                parentNode.highlightArr[index] += 1;
            }, treeArr);
            foundNode.data.quantity = quantity;
        }
        if (quantity === 0) {
            highlightParent(foundNode, (parentNode) => {
                const value = parentNode.highlightArr[index];
                parentNode.highlightArr[index] = (value - 1) > 0 ? value - 1 : 0;
            }, treeArr)
            delete foundNode.data.quantity;
        } else {
            foundNode.data.quantity = quantity;
        }
    }
}

const highlightParent = (node, callback, treeArr) => {
    // parentNode.highlightArr=[резерв, что заказывал в прошлом, реальный заказ ]
    while (node) {
        const parentNode = findNodeById(treeArr, node.parent);
        if (parentNode) {
            parentNode.highlightArr = (parentNode.highlightArr || [0, 0, 0]);
            callback(parentNode);
        }
        node = parentNode;
    }
}


export {
    findNodeById,
    deleteNode,
    traverseTree,
    buildTreeArr,
    addLocalStorageDataToTree,
    addQuantityToTree,
    highlightParent,
    getValueLocalStorage,
    transformTextOrderToObj,
    addHighLightlDataToTreeArr
}
