import React from 'react';

import css from "./BurgerMenu.module.css";

const BurgerMenu = ({isOpen = false, setIsOpen}) => {
    return (
        <div
            className={[css.burger, isOpen ? css.active : ""].join(" ")}
            onClick={()=>setIsOpen(!isOpen)}
        >
            <span></span>
        </div>
    );
};

export {BurgerMenu}