import CryptoJS from "crypto-js"

const passwordFormatted = (passw) => {
    while (passw && passw.length < 16) {
        passw += passw;
    }
    return passw.slice(0, 16);
}
const decrypt = (encryptedText, secretKey) => {
    const decrypted = CryptoJS.AES
        .decrypt(encryptedText, passwordFormatted(secretKey))
        .toString(CryptoJS.enc.Utf8);
    return decrypted
}

export {decrypt}