import {createHashRouter, Navigate} from "react-router-dom";
import {MainLayout} from "./layouts/MainLayout";
import {Color} from "./components/Color/Color";
import {PriceListPage} from "./Pages/PriceListPage";
import {SubsribePage} from "./Pages/SubsribePage";
import {UserRolePage} from "./Pages/UserRolePage";
import {DialogLayout} from "./layouts/DialogLayout";
import {UpdateData} from "./components/UpdateData/UpdateData";
import {RequireSecretKey} from "./hoc/requireSecretKey";
import {TmpPage} from "./Pages/TmpPage";
import {About} from "./Pages/About";
import {OrdersPage} from "./Pages/Orders";

const router = createHashRouter([
    {
        path: "/", element: <MainLayout/>, children: [
            {index: true, element: <Navigate to={'orders'} replace/>},
            {path: "products", element: <RequireSecretKey> <PriceListPage/> </RequireSecretKey>},
            {path: "color", element: <Color/>},
            {path: "about", element: <About/>},
            {path: "orders", element: <RequireSecretKey><OrdersPage/></RequireSecretKey>},
            {path: "update", element: <UpdateData/>},
            {path: "orders/:id", element: <RequireSecretKey> <PriceListPage/> </RequireSecretKey>},
            {path: "tmp", element: <TmpPage/>},

            {path: "*", element: <div>NoPage</div>}
        ]
    },
    {
        path: "/", element: <DialogLayout/>, children: [
            {path: "roles", element: <UserRolePage/>},
            {path: "form", element: <SubsribePage/>},
        ]
    }
])

export {router};

export const navBarLinks = [
    {title: "Subscribe", goTo: "/form", tgFalseIsVisible: false},
    {title: "Замовлення", goTo: "/orders", tgFalseIsVisible: true},
    {title: "Прайс лист", goTo: "/products", tgFalseIsVisible: true},
    {title: "Про", goTo: "/about", tgFalseIsVisible: true},
]
