import React from 'react';
import {PiTelegramLogo} from "react-icons/pi";
import {Button} from "../../Button/Button";

const ButtonSendToTelegram = ({handleOrderSendToTelegram,item}) => {
    const styleObj = {
        fontSize: "1.2em",
        background: "var(--primary-color)"
    }
     if(!item?.totalAmount) return null;
    return (
        <Button style={styleObj} onClick={() => handleOrderSendToTelegram(item)}>
            <PiTelegramLogo/>
        </Button>
    );
};

export {ButtonSendToTelegram};