import React from 'react';

import { FaFileImport } from "react-icons/fa";
import {Button} from "../../Button/Button";
import {useSelector} from "react-redux";

const ButtonImport = ({handleOrderImport}) => {
    const styleObj = {
        fontSize: "1.2em",
    }
    const dateOfPriceList =useSelector(state => state.data.dateOfPriceList);
    // todo ButtonImport visible hide
    if(!dateOfPriceList) return null;

    return (
        <Button style={styleObj} onClick={handleOrderImport}>
            <FaFileImport/>
        </Button>
    );
};

export  {ButtonImport};