import React, {useRef, useState} from 'react';

import css from "./EditData.module.css"
import {Button} from "../Button/Button";
import {useSelector} from "react-redux";

const EditData = ({setIsModalOpened, editObj = {}, editObjArr = [], content}) => {
    const currentUser = useSelector(state => state.app.currentUser)
    const inputRef = useRef();
    // console.dir(content);

    const optioanalObj = {}
    editObjArr.forEach(item => {
        optioanalObj[item.key] = currentUser[item.key] || "";
    })
    const newUser = {...currentUser, ...optioanalObj}

    if (Object.keys(editObj).length === 0) {
        editObj = {
            companyName: {placeholder: "назва організації", value: ""},
            companyId: {placeholder: "код 1С організації", value: ""}
        }
    }

    // const [data, setData] = useState(editObj)
    const [data, setData] = useState(newUser)
    const keys = Object.keys(data);

    const handleFocus = () => {
        if (inputRef.current) {
            inputRef.current.select(); // Выделяем текст
        }
    }

    const handleChange = (e, key) => {
        data[key].value = e.target.value;
        setData({...data})
    }
    const handleEnter = () => {
        setIsModalOpened(false);
    }

    const renderContent = (item) => {
        if(!item) return null;
        return (
            <>
                <div className={css.name}>{item.firstName} {item.lastName}</div>
                <div className={css.dop_info}>{item.dopInfo}</div>
            </>
        )
    }

    return (
        <div className={css.edit_data}>
            {renderContent(currentUser)}
            <div className={css.title}>Введіть додаткову інформацію про:</div>
            <div className={css.name}>{currentUser.firstName} {currentUser.lastName}</div>

            <div className={css.dop_info}>{currentUser.dopInfo}</div>


            {keys?.map(key =>

                <input key={key} type="text"
                       onFocus={handleFocus}
                       onChange={(e) => handleChange(e, key)}
                       value={data[key].value}
                       placeholder={data[key].placeholder}
                />
            )}
            <Button className={css.btn} onClick={handleEnter}>Enter</Button>
        </div>
    );
};

export {EditData};