import React, {useEffect, useState} from 'react';
import css from "./Dialog.module.css"
import {Button} from "../Button/Button";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {useDispatch} from "react-redux";


// todo make this code simple
const EditNameDialog = ({closeModal,currentItem,setCurrentItem}) => {
    const addEditNode = () => {
        if (!currentItem) {
            dispatch(dataSourceActions.ordersAddNode({node: currentItem, name: value}))
        } else {
            dispatch(dataSourceActions.ordersUpdateNode({node: currentItem, name: value}))
        }
        setCurrentItem(null)
    }

    const [value, setValue] = useState("");
    const dispatch = useDispatch();

    const modalInfo = {
        "0": {title: "Назва покупця:", placeholder: "введіть назву покупця"},
        "1": {title: "Назва, комент для заказу:", placeholder: "введіть коментарій"}
    }
    const level = currentItem?.level || "0";

    useEffect(() => {
        setValue(currentItem?.name || "")
    }, [currentItem]);

    const handleInputChange = (e) => {
        setValue(e.target.value);
    }

    const handleEdit = () => {
        setValue("");
        setCurrentItem(null);
        dispatch(dataSourceActions.setIsModalOpen(true));
        addEditNode()
        closeModal()
    }


    const styleObj = {fontSize: "1.2em"};

    return (
        <div className={css.wrapper}>
            <div>{modalInfo[level].title}</div>
            <input
                type="text"
                placeholder={modalInfo[level].placeholder}
                onChange={handleInputChange}
                name="value"
                value={value}
                onFocus={e => {
                    e.target.select()
                }}
            />

            <Button onClick={handleEdit} style={styleObj}>Зберегти</Button>
            <Button onClick={closeModal} style={styleObj}>Закрити</Button>

        </div>
    );
};

export {EditNameDialog};