import React from 'react';
import {appConstants} from "../../constants/appConstants";

const ShowDateUpdate = () => {
    const {localStorageKeyDatePriceList} = appConstants
    const dateUpdate = localStorage.getItem(localStorageKeyDatePriceList)?.replaceAll('"',"");
    if (!dateUpdate) return null
    return (
        <div style={{fontSize:"14px"}}>
            <div>Залишки оновлені на</div>
            <div>{dateUpdate}</div>
        </div>
    );
};

export {ShowDateUpdate};