import React, {useEffect} from 'react';
import {Navigate, useLocation, useSearchParams} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";
import {dataSourceActions} from "../redux/slices/dataSource.slice";

const RequireSecretKey = ({children}) => {
    const [searchParams] = useSearchParams();
    const secretKey = searchParams.get("secretKey") || null;
    const location = useLocation();

    const dispatch = useDispatch();
    const {hasFreshData, actionFreshData} = useSelector(state => state.data)
    useEffect(() => {
        if (hasFreshData === null) {
            dispatch(dataSourceActions.getHasFreshData())
        }
    }, [dispatch, hasFreshData])
    if (hasFreshData) {
        return <Navigate to={"/update"} replace state={{from: location, actionFreshData, secretKey}}/>
    }


    return (
        <div>
            {children}
        </div>
    );
};

export {RequireSecretKey};