import React from 'react';
import {useDispatch, useSelector} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";

import css from "./TreeView.module.css";
import {WithBorderHover} from "../../hoc/withBorderHover/withBorderHover";
import {HighLight} from "../Highlight/HighLight";
import {ArrowButton, HighLightSearchStr} from "./utils.TreeView";

const formatter = new Intl.NumberFormat("uk-UK", {minimumFractionDigits: 2});

const TreeViewProduct = ({item, setIsModalOpened}) => {
    const {expandedRows} = useSelector(state => state.data);
    const dispatch = useDispatch();
    const {id, name, data, children} = item;
    const filterStr = useSelector(state => state.data?.filterStr);

    const openModal = () => {
        dispatch(dataSourceActions.setSelectedItem({selectedItem: item}))
        setIsModalOpened(true);
    }


    const handleClickArrow = () => {
        dispatch(dataSourceActions.toggleExpendedRows(id));
    };
    const renderDataField = () => {
        return (
            <div className={css.column}>
                <div className={css.price}>{formatter.format(data.price)}</div>
                <div className={css.stock}>{data.stock} {data.unit} </div>
                {data?.quantity && <div className={css.quantity}>{data.quantity}</div>}
            </div>
        )
    }
    const renderChildren = () => {
        return expandedRows.includes(id) && children && (
            <div className={css.sub_title}>
                {children.map((subitem) => <TreeViewProduct key={subitem.id} item={subitem} setIsModalOpened={setIsModalOpened}/>)}
            </div>
        );
    }


    return (
        <>
            <WithBorderHover>
                <div className={css.row} onClick={data ? openModal : () => { }}>
                    <div style={{display: "flex", width: "100%"}}>
                        <ArrowButton item={item} isExpanded={expandedRows.includes(id)} handleClick={handleClickArrow}/>

                        {data?(
                            <div className={ css.title }>
                                <div className={css.marker}><HighLight highLightArr={item.highlightArr}/></div>
                                <HighLightSearchStr text={name} searchStr={filterStr}/>
                            </div>
                        ): (
                            <div className={ css.group}  onClick={handleClickArrow}>
                                <div className={css.marker}><HighLight highLightArr={item.highlightArr}/></div>
                                {name}
                            </div>
                        )}
                    </div>

                    {data ? renderDataField() : null}
                </div>
            </WithBorderHover>

            {renderChildren()}
        </>
    );
};

export {TreeViewProduct};