import {configureStore} from "@reduxjs/toolkit";
import {dataSourceReducer} from "./slices/dataSource.slice";
import {appHelperReducer} from "./slices/appHelper.slice";

import {appConstants} from "../constants/appConstants";
const {localStorageKeyOrders,localStorageKeyCart}=appConstants
const store =configureStore({
    reducer:{
        data:dataSourceReducer,
        app:appHelperReducer
    },
    middleware: (getDefaultMiddleware) =>
        getDefaultMiddleware({
            serializableCheck: false,
        }),
})
store.subscribe(() => {
    localStorage.setItem(localStorageKeyOrders, JSON.stringify(store.getState().data.orders));
    localStorage.setItem(localStorageKeyCart, JSON.stringify(store.getState().data.cart));
});

export {store}