import React from 'react';

import css from "./Dialog.module.css";
import {Button} from "../Button/Button";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {useDispatch, useSelector} from "react-redux";

const ImportTextOrderDialog = ({importOrder, setImportOrder}) => {
    const dispatch = useDispatch();
    const clipboardText = useSelector(state => state.data.clipboardText)


    const handlePasteClipboard = async () => {
        dispatch(dataSourceActions.setTextFromClipboard())
    }

    const handleClearTextArea = () => {
        dispatch(dataSourceActions.setClipboardText(""))
    }
    const handleChangeTextAria = (e) => {
        dispatch(dataSourceActions.setClipboardText(e.currentTarget.value))
    }
    const handleClose = () => {
        setImportOrder(null)
    }
    const handleSave = ({importOrder}) => {
        dispatch(dataSourceActions.addTextOrderToTreeOrders({orderId: importOrder.id}))
        dispatch(dataSourceActions.setClipboardText(""))//clear TextArea
        setImportOrder(null); // close Modal
    }

    return (
        <div className={css.wrapper}>
            <label htmlFor="story"><p>Поле для вставки текста замовлення з буфера обміну</p> <p>Натисніть на
                відповідну кнопку</p></label>
            <textarea
                id="story"
                name="story"
                rows="5" cols="33"
                value={clipboardText}
                onChange={(e) => handleChangeTextAria(e)}
            >
                </textarea>
            <div className={css.row_btn}>
                <Button onClick={handlePasteClipboard}>Вставити з Буфера обміну</Button>
                <Button onClick={handleClearTextArea}>Очистити</Button>
            </div>
            <Button onClick={() => handleSave({importOrder})}>Зберегти</Button>
            <Button onClick={handleClose}>Закрити</Button>
        </div>


    );
};

export {ImportTextOrderDialog};