import {appConstants} from "../../constants/appConstants";
import {useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {appHelperActions} from "../../redux/slices/appHelper.slice";

const {fontSizeMax, fontSizeMin, fontSizeStep} = appConstants;
const FontSizeChanger = () => {

    const initFontSize = useSelector(state => state.app.fontSize)
    const [fontSize, setFontSize] = useState(initFontSize);
    const dispatch = useDispatch();
    const handleChange = (e) => {
        const value = e.target.value;
        setFontSize(value);
        dispatch(appHelperActions.setFontSize(value))
    }
    return (
        <div style={{display: "flex", flexDirection: "column", alignItems: "center"}}>
            <div style={{fontSize:"0.6em"}}>Розмір шрифта</div>
            <input type="range"
                   min={fontSizeMin}
                   max={fontSizeMax}
                   step={fontSizeStep}
                   value={Number(fontSize) ||1}
                   onChange={(e) => handleChange(e)}
            />
        </div>
    );
};

export {FontSizeChanger};