import React, {useEffect, useState} from 'react';
import {Button} from "../Button/Button";
import {useTelegram} from "../../hooks/useTelegram";
import css from './Header.module.css';
import {NavBar} from "../NavBar/NavBar";
import {BurgerMenu} from "../BurgerMenu/BurgerMenu";
import {WithBorderHover} from "../../hoc/withBorderHover/withBorderHover";
import {FontSizeChanger} from "../FontSizeChanger/FontSizeChanger";
import {useLocation} from "react-router-dom";
import {headerDynamicData} from "./headerDynamicData";
import {ShowDateUpdate} from "../ShowDateUpdate/ShowDateUpdate";
import {useDispatch} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";

const Header = () => {
    const location = useLocation();
    const {user, onClose} = useTelegram();
    const [isOpen, setIsOpen] = useState(false);
    const {isTgOn} = useTelegram();
    const dispatch = useDispatch();

    const convertPathToKey = (path) => {
        const keys = ["orders", "products"];
        const pathParts = path.split("/");
        for (let i = 1; i < pathParts.length; i++) {
            if (!keys.includes(pathParts[i])) {
                pathParts[i] = ":id"
            }
        }
        return pathParts.join("/")
    }

    const handleClearAll=()=>{
        localStorage.clear();
        dispatch(dataSourceActions.resetState());
        dispatch(dataSourceActions.clearOrders());
    }

    const renderButton = headerDynamicData()[convertPathToKey(location.pathname)]?.btn;
    const renderInfo = headerDynamicData()[convertPathToKey(location.pathname)]?.info;

    // Swipe handler:
    useEffect(() => {
        let startTouchX = 0;
        let endTouchX = 0;
        let startTouchY = 0;
        let endTouchY = 0;

        document.addEventListener("touchstart", (event) => {
            startTouchX = event.changedTouches[0].pageX;
            startTouchY = event.changedTouches[0].pageY;
        })
        document.addEventListener("touchend", (event) => {
            endTouchX = event.changedTouches[0].pageX;
            endTouchY = event.changedTouches[0].pageY;
            // if (
            //     startTouchX < 100 && Math.abs(endTouchY - startTouchY) < 40 && endTouchX > startTouchX
            // ) {
            //     setIsOpen(true)
            // }
            // ;
            if (
                startTouchX > 240 && Math.abs(endTouchY - startTouchY) < 40 && endTouchX < startTouchX
            ) {
                setIsOpen(false)
            }
        })


    }, []);

    return (
        <div className={css.header}>
            <NavBar isOpen={isOpen}>
                <div>{user?.username}</div>
                <Button style={{fontSize: "0.5em"}} onClick={handleClearAll}>Видалити Всі дані</Button>
                <ShowDateUpdate/>
                <FontSizeChanger/>
                {isTgOn && <Button onClick={onClose}>Закрыть</Button>}
            </NavBar>
            <div className={css.wrapper_info}  >
            {renderInfo}
            </div>
            {renderButton}

            <div className={css.burger}>
                <WithBorderHover>
                    <BurgerMenu isOpen={isOpen} setIsOpen={setIsOpen}/>
                </WithBorderHover>
            </div>
        </div>
    );
};

export {Header};