import React, {useEffect, useState} from 'react';
import {Button} from "../Button/Button";

import css from "./NumericKeyboard.module.css"
import {WithBorderHover} from "../../hoc/withBorderHover/withBorderHover";
import {useDispatch, useSelector} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";

const NumericKeyboard = ({closeModal}) => {


    const inputRef = React.useRef(null);
    const [quantity, setQuantity] = useState("0");
    const dispatch = useDispatch();
    const selectedItem = useSelector(state => state.data.selectedItem);

    useEffect(() => {
        const value = selectedItem?.data?.quantity || "0";
        setQuantity("" +value)

    }, [selectedItem]);

    const handleFocus=()=>{
        if (inputRef.current) {
            inputRef.current.select(); // Выделяем текст
        }
    }

    const handleNext = () => {
        dispatch(dataSourceActions.setQuantity(quantity))
        dispatch(dataSourceActions.addToCart(selectedItem));
        dispatch(dataSourceActions.addQuantityToTreeViewProducts({itemId: selectedItem.id}));
        closeModal(false);
    }

    const handleButtonClick = (value) => {
        if (value === 'C') {
            setQuantity("");
        } else if (value === 'Enter') {
            // setQuantity('0');
            handleNext()
        } else if (value === '<') {
            if (quantity.length === 0) {
                setQuantity("0")
            } else {
                const newValue = quantity.slice(0, -1)
                setQuantity(newValue)
            }
        } else {
            const regexp = /^0+/
            setQuantity(prev => (prev + value).replace(regexp, '').slice(0, 6))
        }
    };

    const buttons = [
        ['1', '2', '3', '4'],
        ['5', '6', '7', '8'],
        ['C', '9', '0', '<'],
        ['Enter']
    ];


    return (
        <div className={css.keyboard}>
            <input type="text"
                   // autoFocus
                onFocus={handleFocus}
                   value={quantity}
                   readOnly
            />
            {buttons.map((row, index) => (<div key={index} className={css.row}>
                    {generateBtn(row, handleButtonClick)}
                </div>

            ))}
        </div>
    )
};

export {NumericKeyboard};

const styleObj = {
    "C": {color: "var(--error-color)", backgroundColor: "var(--warning-color)"},
    "<": {color: "var(--text-color)", backgroundColor: "var(--warning-color)"},
    "Enter": {color: "var(--text-color)", backgroundColor: "var(--success-color)"}
}
const generateBtn = (row, handleButtonClick) => {
    return row.map(btn => (
        <WithBorderHover key={btn}>
            <Button className={css.btn} style={styleObj[btn]} key={btn}
                    onClick={() => handleButtonClick(btn)}>{btn}</Button>
        </WithBorderHover>
    ))
}
