import {createAsyncThunk, createSlice, isFulfilled, isPending, isRejected} from "@reduxjs/toolkit";
import {decrypt} from "../../utils/crypto";
import {dataService} from "../../services/dataService";
import {
    addLocalStorageDataToTree, addQuantityToTree,
    buildTreeArr, deleteNode, findNodeById, getValueLocalStorage, transformTextOrderToObj
} from "./utils.slice";

import {appConstants} from "../../constants/appConstants";
import {v4 as uuidv4} from "uuid";
import {formatPrice} from "../../components/TreeViewContainer/utils.TreeView";

const {localStorageKeyDatePriceList, localStorageKeyCart, localStorageKeySource, localStorageKeyOrders} = appConstants;


const getHasFreshData = createAsyncThunk(
    "dataSource/getHasFreshData",
    async (_, thunkAPI) => {

        try {
            const response = await dataService.getDateUpdate();

            const {dateUpdate: freshDateUpdate} = response;
            const dataSource = getValueLocalStorage(localStorageKeySource)
            const dateUpdate = dataSource?.dateUpdate || null;

            let result = {hasFreshData: false, actionFreshData: null, dateUpdate}
            const diff = new Date(freshDateUpdate) - new Date(dateUpdate);
            if (!dateUpdate) {
                result = {hasFreshData: true, actionFreshData: "toLoad", dateUpdate}
            } else if (diff > 0) {
                result = {hasFreshData: true, actionFreshData: "toRefresh", dateUpdate}
            }
            return thunkAPI.fulfillWithValue(result);
        } catch (e) {
            console.log(e);
            const response=e.message || "Нема можливості оновити дані";
            // if (e.code === "ERR_NETWORK") {
            //     return {hasFreshData: false, actionFreshData: "ERR_NETWORK"}
            // }
            return thunkAPI.rejectWithValue(response)
        }
    })

const copyOrderToClipboard = createAsyncThunk(
    "dataSource/copyOrder",
    async (order, thunkAPI) => {
        try {
            const headers = ["code", "quantity", "amount"];
            const result = {headers, values: []};
            let arr = order?.children

            arr.forEach((item) => {
                const values = []
                headers.forEach((header, index) => {
                    const value = item.data[header]

                    values[index] = value.toString().replace(/^0+/, '');
                })
                result.values.push(values)
            })

            await navigator.clipboard.writeText(JSON.stringify(result));
            const newOrder = {...order, clipboard: new Date().toLocaleString("uk-UK")}

            const message = encodeURIComponent(`Замовлення:\n${new Date().toLocaleString("uk-UK")} \nна суму ${formatPrice(+order.totalAmount)}\n\n${JSON.stringify(result)}`);
            window.open(`https://t.me/share/url?url=${message}`, '_blank');

            return {newOrder, orderId: order.id};
        } catch (e) {
            const response="Щось не так з копіюваннєм заказу до Буферу обміну"
            return thunkAPI.rejectWithValue(response);
        }
    }
)

const setTextFromClipboard = createAsyncThunk(
    "dataSource/pasteClipboard",
    async (_, thunkAPI) => {
        try {
            return await navigator.clipboard.readText();
        } catch (e) {
            const response="Не можу прочитати дані з буферу обміну"
            return thunkAPI.rejectWithValue(response);
        }
    }
)

const setSourceData = createAsyncThunk(
    "dataSource/setData",
    async ({secretCode}, thunkAPI) => {
        try {
            const {dateUpdate} = await dataService.getDateUpdate();
            const {dateUpdate: datePriceList, data} = await dataService.getData();
            const result = {data: JSON.parse(decrypt(data, secretCode)), dateUpdate, datePriceList, filter: ""};
            localStorage.setItem(localStorageKeySource, JSON.stringify(result));
            localStorage.setItem(localStorageKeyDatePriceList, JSON.stringify(datePriceList));

            return thunkAPI.fulfillWithValue(result);
        } catch (e) {
            let response = ""
            if (e.message === "Malformed UTF-8 data") {
                response = "Код не вірний"
            } else {
                response = e.message || "Не можу отримати або зберегти оновлені дані";
            }

            return thunkAPI.rejectWithValue(response)
        }
    }
)
//todo selectedItem, currentOrderInfo дубляж!!!!!!!
const initialState = {
    errors: null,
    userRole: "manager",
    hasFreshData: null,
    actionFreshData: null,
    dateOfPriceList: null,
    isLoading: false,
    TreeViewProducts: [],
    expandedRows: [],
    selectedItem: {},
    cart: [],
    quantity: 0,
    totalAmount: 0,
    filterStr: "",
    orders: getValueLocalStorage(localStorageKeyOrders) || [],
    isModalOpen: false,
    currentOrderInfo: null,
    clipboardText: "",
}
export const dataSourceSlice = createSlice({
    name: "source",
    initialState,
    reducers: {
        setTreeViewProducts: (state, action) => {
            const currentOrderId = state.currentOrderInfo?.currentOrderId;
            let localStorageCart = [];
            const filterObj = action.payload || {}
            const productList = getValueLocalStorage(localStorageKeySource)?.data || [];

            const tree = buildTreeArr(productList, filterObj);

            // add data from localStorage from "orders" or from "cart" to treeView
            if (currentOrderId) {
                const orders = getValueLocalStorage(localStorageKeyOrders)
                localStorageCart = findNodeById(orders, currentOrderId)?.children || [];
            } else {
                localStorageCart = getValueLocalStorage(localStorageKeyCart) || [];
            }
            const fields = ["code", "quantity", "amount"];
            const newTree = addLocalStorageDataToTree(tree, localStorageCart, fields);
            console.log(newTree);
            state.TreeViewProducts = newTree;
        },

        toggleExpendedRows: (state, action) => {
            const index = action.payload;
            const expandedRows = state.expandedRows;
            if (expandedRows.includes(index)) {
                state.expandedRows = expandedRows.filter(rowIndex => rowIndex !== index);
            } else {
                state.expandedRows.push(index)
            }
        },

        setExpendedRows: (state, action) => {
            const index = action.payload;
            const expendedRows = state.expandedRows;
            if (!expendedRows.includes(index)) {
                state.expandedRows.push(index);
            }
        },

        setSelectedItem: (state, action) => {
            const {selectedItem} = action.payload;
            state.selectedItem = selectedItem;
        },
        clearOrders: (state) => {
            state.orders = [];
        },

        setQuantity: (state, action) => {
            const quantity = action.payload;
            state.quantity = Number(quantity);
        },

        addToCart: (state, action) => {
            const currentOrderId = state.currentOrderInfo?.currentOrderId || action.payload?.orderId
            const orders = JSON.parse(JSON.stringify(state.orders));
            let cart = {};
            let cartAmount = 0;
            let cartData = [];
            if (currentOrderId) {

                cart = findNodeById(orders, currentOrderId);
                cartAmount = cart.totalAmount || 0;
                cartData = cart.children || [];
            } else {

                cartData = JSON.parse(JSON.stringify(state.cart));
                cartAmount = state.totalAmount;
            }
            const newProduct = {...action.payload, orderId: currentOrderId, level: "2"};
            const price = Number(newProduct.data.price);
            const amount = Number((price * state.quantity).toFixed(2));
            try {
                const exist = cartData.find((product) => product.id === newProduct.id);
                if (exist) {
                    exist.data.quantity = state.quantity;
                    const diffTotalAmount = Number(exist.data.amount) - amount;
                    exist.data.amount = amount;

                    cartAmount = Number((cartAmount - diffTotalAmount).toFixed(2));
                } else {
                    cartData.push({
                        ...newProduct, data: {
                            ...newProduct.data,
                            amount,
                            quantity: state.quantity
                        }
                    });
                    cartAmount += amount;
                }
                //     delete items with amount =0:
                cartData.forEach((item, index) => {
                    if (item.data?.quantity === 0) {
                        cartData.splice(index, 1)
                    }
                })
                if (currentOrderId) {
                    cart.totalAmount = cartAmount;
                    state.orders = orders;
                } else {
                    state.cart = cartData;
                    state.totalAmount = cartAmount;
                }
                state.currentOrderInfo = {...state.currentOrderInfo, totalAmount: cartAmount}
            } catch (e) {
                console.error(e)
            }
        },

        addQuantityToTreeViewProducts: (state, action) => {
            const quantity = state.quantity;
            const tree = state.TreeViewProducts;
            const {itemId} = action.payload;
            addQuantityToTree(tree, itemId, quantity)
            state.quantity = 0;
        },

        setFilterStr: (state, action) => {
            state.filterStr = action.payload || ""
        },


        ordersAddNode: (state, action) => {
            const {node, name} = action.payload;
            if (!node) {
                const newNode = {id: uuidv4(), level: "0", name, parentId: null, children: []};
                state.orders.push(newNode)
            } else {
                const parentNode = findNodeById(state.orders, node.id)
                parentNode.children.push(node);
            }
            localStorage.setItem(localStorageKeyOrders, JSON.stringify(state.orders))

        },

        ordersUpdateNode: (state, action) => {
            const {name: newName, node} = action.payload;

            const nodeToUpdate = findNodeById(state.orders, node.id);
            if (nodeToUpdate) {
                nodeToUpdate.name = newName;
            }
            localStorage.setItem(localStorageKeyOrders, JSON.stringify(state.orders));
        },

        deleteNode: (state, action) => {
            const nodeId = action.payload;

            deleteNode(state.orders, nodeId);
            localStorage.setItem(localStorageKeyOrders, JSON.stringify(state.orders));
        },

        insertNode: (state, action) => {
            const {parentId, level} = action.payload;
            const treeArray = state.orders;
            const newNode = {name: "", level, parentId, date: new Date().toISOString(), id: uuidv4(), children: []};
            const traverse = (node) => {
                if (node.hasOwnProperty("data")) return
                if (node.id === parentId) {
                    node.children.push(newNode)
                } else {
                    node.children.forEach(child => {
                        traverse(child)
                    })
                }
            }
            treeArray.forEach(node => {
                traverse(node)
            })
            localStorage.setItem(localStorageKeyOrders, JSON.stringify(treeArray))
        },

        setIsModalOpen: (state, action) => {
            state.isModalOpen = action.payload;
        },
        // todo setOrderToPreview ?
        setOrderToPreview: (state, action) => {
        },
        setNamesOfOrderById: (state, action) => {
        },
        setCurrentOrderInfo: (state, action) => {
            const currentOrderId = action.payload || null;
            if (!currentOrderId) {
                // state.currentOrderInfo = null;
                state.currentOrderInfo = {totalAmount: state.totalAmount};
                return
            }
            const orders = state.orders;
            const foundNode = findNodeById(orders, currentOrderId);
            if (!foundNode) {
                state.currentOrderInfo = null;
                return;
            }
            const date = new Date(foundNode.date).toLocaleString(appConstants.local)
            const orderName = {orderName: `${foundNode.name} ${date}`}
            const customerName = findNodeById(orders, foundNode.parentId).name
            const totalAmount = foundNode?.totalAmount || 0

            state.currentOrderInfo = {...orderName, customerName, currentOrderId, totalAmount};
        },

        setClipboardText: (state, action) => {
            state.clipboardText = action.payload || "";
        },

        addTextOrderToTreeOrders: (state, action) => {
            try {
                const customerId = action.payload.orderId;
                const newNode = {
                    name: "",
                    level: 1,
                    parentId: customerId,
                    id: uuidv4(),
                    date: new Date().toISOString(),
                    totalAmount: "",
                    children: []
                }
                const orderText = state.clipboardText;
                const orders = state.orders;
                const foundNode = findNodeById(orders, customerId);
                if (!foundNode) return;
//todo ЕСЛИ что-то пошло не так !!!!!!
                const products = getValueLocalStorage(localStorageKeySource)?.data;
                if (products && products.length === 0) console.error("products is null!!!!!!!!!!!!")

                let totalAmount = 0;
                const additionalData = transformTextOrderToObj(orderText);
                additionalData.forEach(item => {
                    const foundProduct = products.find(product => {
                        if (product?.data?.code && product?.data?.code === item.code) {
                            totalAmount += Number(item.quantity) * Number(product.data.price)
                            return product
                        } else return null;
                    })
                    if (foundProduct) {
                        foundProduct.orderId = newNode.id;
                        foundProduct.level = 2;
                        foundProduct.data = {...foundProduct.data, ...item};
                        newNode.children.push(foundProduct);
                        newNode.totalAmount = totalAmount;
                    }
                })
                newNode.receive = new Date().toISOString()
                foundNode.children.push(newNode)

                state.orders = orders;
                // todo extract to function
                const expendedRows = state.expandedRows;
                if (!expendedRows.includes(newNode.id)) {
                    state.expandedRows.push(newNode.id);
                }


            } catch (e) {
                console.error(e.message);
            }
        },

        setHasFreshData: (state, action) => {
            state.hasFreshData = action.payload;
        },
        setError: (state, action) => {
            state.errors = action.payload
        },
        resetState: () => initialState,

    },
    extraReducers: builder =>
        builder
            .addCase(getHasFreshData.fulfilled, (state, action) => {
                const {hasFreshData, actionFreshData, dateUpdate} = action.payload;
                state.hasFreshData = hasFreshData;
                state.actionFreshData = actionFreshData;
                state.dateOfPriceList = dateUpdate;
            })
            .addCase(setSourceData.fulfilled, (state, action) => {
                const datePriceList = action.payload.datePriceList;
                state.dateOfPriceList = datePriceList?.slice(-10);
                state.hasFreshData = false;
            })
            .addCase(copyOrderToClipboard.fulfilled, (state, action) => {
                const orderId = action.payload?.orderId;
                const orders = state.orders;
                const foundNode = findNodeById(orders, orderId);
                if (foundNode) {
                    if (!foundNode?.send) foundNode.send = [];
                    foundNode.send.push(new Date().toISOString())
                }

                state.orders = orders;

            })
            .addCase(setTextFromClipboard.fulfilled, (state, action) => {
                const text = action.payload || "";
                state.clipboardText = text;
            })

            .addMatcher(isRejected(setSourceData, getHasFreshData, copyOrderToClipboard, setTextFromClipboard), (state, action) => {
                console.log(action);
                state.errors = action.payload || action.error.message;
                state.isLoading = false;
            })
            .addMatcher(isPending(setSourceData, getHasFreshData, copyOrderToClipboard, setTextFromClipboard), state => {
                state.isLoading = true;
            })
            .addMatcher(isFulfilled(setSourceData, getHasFreshData, copyOrderToClipboard, setTextFromClipboard), state => {
                state.isLoading = false;
                state.errors = null;
            })
})

const {reducer: dataSourceReducer, actions} = dataSourceSlice;

const dataSourceActions = {
    ...actions,
    setSourceData,
    getHasFreshData,
    copyOrderToClipboard,
    setTextFromClipboard
}

export {dataSourceReducer, dataSourceActions}