import React, {useEffect, useRef, useState} from "react";
import css from "./Search.module.css";
import {Button} from "../Button/Button";
import {FaSearch} from "react-icons/fa";

import {MdOutlineSearchOff} from "react-icons/md";
import {CheckBoxOrAnd} from "../CheckBoxOrAnd/CheckBoxOrAnd";
import {appConstants} from "../../constants/appConstants";
import {useDispatch} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";

const Search = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [showFilterKey, setShowFilterKey] = useState(false);
    const [filterKey, setFilterKey] = useState("OR");

    const [filterStr, setFilterStr] = useState("");
    const inputRef = useRef();
    const {durationDebounce,durationShowVisible} = appConstants;

    const dispatch = useDispatch();
    useEffect(() => {
        const timeoutId = setTimeout(() => {
            dispatch(dataSourceActions.setTreeViewProducts({filterStr, filterKey}))
            dispatch(dataSourceActions.setFilterStr(filterStr))
        }, durationDebounce)

        return () => clearTimeout(timeoutId);
    }, [filterStr, filterKey, dispatch, durationDebounce]);

    const toggleContext = () => {
        setIsOpen((prev) => {
            if (!prev) {
                inputRef.current.focus();
            }
            if (prev) {
                setFilterStr("")
            }
            return !prev
        });
    };
    const styleObj = {
        false: {color: "var(--link-color)", background: "var(--heading-color)",fontSize: "1.3em"},
        true: {color: "var(--error-color)", background: "var(--warning-color)",fontSize:"1.4em"},
    }

    const handleInputChange = (event) => {
        setFilterStr(event.target.value);
        setShowFilterKey(true);
        setTimeout(() => {
            setShowFilterKey(false);
        }, durationShowVisible); // Скрыть через 3 секунды
    };
    const onKeyPressHandler = (e) => {
        if (e.charCode === 13) {
            toggleContext()
        }
    }
    return (
        <div className={css.search}>
            <div className={isOpen ? [css.context, css.open].join(" ") : css.context}>
                <div className={css.filter_str}>
                    <div className={css.input_container}>
                        <input
                            type="text"
                            placeholder="пошук"
                            onKeyPress={onKeyPressHandler}
                            value={filterStr} // Устанавливаем значение input
                            onChange={handleInputChange}
                            ref={inputRef}
                        />
                    </div>
                </div>
                <CheckBoxOrAnd isVisible={showFilterKey} filterKey={filterKey} setFilterKey={setFilterKey}/>
            </div>
            <Button style={styleObj[isOpen]} onClick={toggleContext}>{isOpen ? <MdOutlineSearchOff/> : <FaSearch/>} </Button>
        </div>
    );
};

export {Search};
