import React from 'react';

import css from "./CurrentOrderInfo.module.css"
import {useSelector} from "react-redux";
import {TbSum} from "react-icons/tb";
import {formatPrice} from "../TreeViewContainer/utils.TreeView";

const CurrentOrderInfo = () => {
    const currentOrderInfo = useSelector(state => state.data.currentOrderInfo);
    if (!currentOrderInfo) return null;
    const orderName = currentOrderInfo.orderName;
    const customerName = currentOrderInfo.customerName;
    const totalAmount = currentOrderInfo.totalAmount;

    return (
        <div className={css.info}>
            {customerName && <div>{customerName}</div>}
            {orderName && <div>{orderName}</div>}
            {totalAmount !== null && +totalAmount > 0 &&
                <div style={{color: "var(--link-color)"}}><TbSum/>{formatPrice(+totalAmount)}</div>}
        </div>
    );
};

export {CurrentOrderInfo};
