import React, {useState} from 'react';

import css from "./withBorderHover.module.css"

const WithBorderHover = ({children}) => {
    const [hover, setHover] = useState(false);

    const hoverOn = () => {
        setHover(true)
    };
    const hoverOff = () => {
        setHover(false);
    };
    return (
        <div
            className={hover ? [css.border, css.hover_effect].join(" ") : css.border}
            onTouchStart={hoverOn}
            onTouchEnd={hoverOff}

        >
            {children}
        </div>
    );
};

export {WithBorderHover};