import {IoMdMore} from "react-icons/io";
import css from "./ButtonMore.module.css";
import {useEffect, useState} from "react";
import {Button} from "../../../Button/Button";
import {appConstants} from "../../../../constants/appConstants";

const ButtonMore = ({children}) => {
    const [isOpened, setIsOpened] = useState(false);
    const durationShowVisible = appConstants.durationShowVisible;

    const styleObj = {
        fontSize: "1.2em",
        paddingLeft: "0.3em",
        paddingRight: "0.3em",
        color: "var(--accent-color)",
        background: "var(--warning-color)"
    }
    useEffect(() => {
        if (isOpened) {
            setTimeout(() => {
                setIsOpened(false)
            }, durationShowVisible)
        }

    }, [isOpened, durationShowVisible]);

    const handleClick = (event) => {
        event.stopPropagation();
        setIsOpened((prev) => !prev)

    }

    return (
        <div
            className={css.button_more}
            onClick={(event) => handleClick(event)}
        >
            <div className={isOpened ? css.display : css.hidden}>
                {children}
            </div>
            <Button style={styleObj}><IoMdMore/></Button>
        </div>
    );
};

export {ButtonMore};