import React, {useEffect, useMemo, useState} from 'react';

import {useDispatch, useSelector} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {TreeViewProduct} from "../TreeViewContainer/TreeViewProduct";
import {Modal} from "../Modal/Modal";
import {ProductCard} from "../../ProductCard/ProductCard";
import {NumericKeyboard} from "../NumericKeyboard/NumericKeyboard";
import {useParams} from "react-router-dom";

const PriceList = () => {
    const dispatch = useDispatch();
    const {id: orderId} = useParams();


    const treeViewList = useSelector(state => state.data.TreeViewProducts?.children)
    const [isModalOpened, setIsModalOpened] = useState(false);


    useEffect(() => {
        dispatch(dataSourceActions.setCurrentOrderInfo(orderId))
        dispatch(dataSourceActions.setTreeViewProducts());

        return () => {
            dispatch(dataSourceActions.setCurrentOrderInfo(null))
        }
    }, [dispatch, orderId]);

    const closeModal = () => {
        setIsModalOpened(false);
    };

    const products = useMemo(() => {
        return treeViewList && treeViewList.map(item => (
            <TreeViewProduct key={item.id} item={item} setIsModalOpened={setIsModalOpened}/>
        ))
    }, [treeViewList])

    return (
        <>
            {products}
            <Modal active={isModalOpened} setActive={closeModal}>
                <ProductCard>
                    <NumericKeyboard closeModal={setIsModalOpened}/>
                </ProductCard>
            </Modal>
        </>
    );
}


export {PriceList};