import {Button} from "../Button/Button";
import {BiSolidDownArrow, BiSolidRightArrow} from "react-icons/bi";
import React from "react";

import {appConstants} from "../../constants/appConstants";

const {currency, local} = appConstants;

const HighLightSearchStr = ({text, searchStr}) => {
    const searchWords = searchStr.split(" ").filter(word => word !== "");
    if (searchWords.length === 0) return <div>{text}</div>
    const searchRegex = new RegExp(searchWords.join("|"), "gi");
    const result = text.replace(searchRegex, (match) => `<mark >${match}</mark>`);
    const markup = {__html: result}

    return (
        <div dangerouslySetInnerHTML={markup}/>
    )
}

const ArrowButton = ({isExpanded, handleClick, item}) => {
    if (!item?.children?.length > 0) return null;

    const styleObj= item.send? {fontSize: "1.4em",background:"var(--primary-color)"}:{fontSize: "1.4em"}
    return (
        <Button style={styleObj} onClick={handleClick}>
            {isExpanded ? <BiSolidDownArrow/> : <BiSolidRightArrow/>}
        </Button>
    )
};


const formatPrice = (number) => {
    return new Intl.NumberFormat(local, {style: 'currency', currency}).format(number)
}

const formatNumber = (number, digit = 2) => {
    return new Intl.NumberFormat(local, {minimumFractionDigits: digit}).format(number)
}

const formatCode = (text, digit = 11) => {
    return text.padStart(digit, '0');
}

export {
    HighLightSearchStr,
    ArrowButton,
    formatNumber,
    formatPrice,
    formatCode
}