import React, {useEffect, useState} from 'react';

import css from "./CheckBoxOrAnd.module.css";
import {CheckBox} from "../CheckBox/CheckBox";

const CheckBoxOrAnd = ({isVisible, filterKey, setFilterKey}) => {
    const initValue = (filterKey === "OR");

    const [valueOR, setValueOR] = useState(initValue);
    const [valueAND, setValueAND] = useState(!initValue);

    useEffect(() => {
        setFilterKey(valueOR ? "OR" : "AND");

    }, [valueOR, setFilterKey]);

    const handleSetOr = () => {
        setValueOR(prev => !prev)
        setValueAND(prev => !prev)
    }
    const handleSetAnd = () => {
        setValueOR(prev => !prev)
        setValueAND(prev => !prev)
    }

    if (!isVisible) return null

    return (
        <div className={css.checkBoxOrAnd}>
            <CheckBox checked={valueOR} onChange={handleSetOr}>OR</CheckBox>
            <CheckBox checked={valueAND} onChange={handleSetAnd}>AND</CheckBox>
        </div>
    );
};

export {CheckBoxOrAnd};