import React, {useState} from 'react';

import css from "./EditUserData.module.css"
import {useTelegram} from "../../hooks/useTelegram";
import {useSearchParams} from "react-router-dom";
import {CheckBox} from "../CheckBox/CheckBox";
import {FaInfo} from "react-icons/fa";
import {Button} from "../Button/Button";
import {Modal} from "../Modal/Modal";
import {EditData} from "../EditData/EditData";
import {useDispatch} from "react-redux";
import {appHelperActions} from "../../redux/slices/appHelper.slice";

const transformDataToUsers = (data) => {
    if (!data) return [];
    const {keys: headers, values: userData} = data;
    const users = userData.map(userArray => {
        return headers.reduce((userObj, key, index) => {
            userObj[key] = userArray[index];
            return {...userObj, isRegister: false};
        }, {});
    });
    return users
}
const EditUserData = () => {
    const {tg} = useTelegram();
    let [searchParams] = useSearchParams();
    const chatId = searchParams.get("chatId") || "";
    const title = searchParams.get("title") || "";


    const dataJSON = JSON.parse(searchParams.get("data"))

    const users = transformDataToUsers(dataJSON);
    const [data, setData] = useState(users)
    const [originalData] = useState(JSON.parse(JSON.stringify(users))) //make a copy of users
    const [isModalOpened, setIsModalOpened] = useState(false);
    const dispatch = useDispatch();


    const closeModal = () => {
        setIsModalOpened(false);
    };

    const isItemChanged = (index) => {
        return JSON.stringify(data[index]) !== JSON.stringify(originalData[index]);
    }

    const getChangedItems = () => {
        const result = data.filter((item, index) => JSON.stringify(item) !== JSON.stringify(originalData[index]));
        console.log(result);
    }
    const onChange = (userId) => {
        const foundUser = data.find(item => item.id === userId)
        foundUser.isRegister = !foundUser.isRegister;
        setData([...data])
    }

    const handleOptionalData = (item) => {
        dispatch(appHelperActions.setCurrentUser(item))
        setIsModalOpened(true)
    }

    const editObjArr = [
        {key: "companyName", placeholder: "назва організації"},
        {key: "companyId", placeholder: "код 1С організації"}
    ]
    const renderContent = (item) => {
        console.log(item);
        if(!item) return null;
        return (

            <>
                <div className={css.name}>{item.firstName} {item.lastName}</div>
                <div className={css.dop_info}>{item.dopInfo}</div>
            </>
        )
    }

    return (
        <div className={css.edit_data}>
            {title && <div className={css.title}>{title}</div>}
            {data?.map((item, index) => (
                <div key={item.id} className={css.row}>
                    <div key={item.id} className={[css.item, isItemChanged(index) ? css.active : ""].join(" ")}>
                        {renderContent(item)}

                    </div>
                    <Button onClick={() => handleOptionalData(item)}><FaInfo/></Button>
                    <CheckBox key={"cb" + item.id} checked={item.isRegister} onChange={(e) => onChange(item.id)}/>

                </div>
            ))}

            <Modal active={isModalOpened} setActive={closeModal}>
                <EditData setIsModalOpened={closeModal} editObjArr={editObjArr} content={()=>renderContent()} />
            </Modal>

            <button onClick={getChangedItems}>Що було змінено:</button>
        </div>
    );

};

export {EditUserData};