import React from 'react';

import {Badge} from "../Badge/Badge";


const HighLight = ({highLightArr}) => {
    // highLightArr = [1, 1, 1]
    const colors = {
        0: {bc: "var(--error-color)", c: "var(--text-color)"},
        2: {bc: "var(--warning-color)", c: "var(--heading-color)"},
        1: {bc: "var(--success-color)", c: "var(--warning-color)"}
    }

    if (!highLightArr || !highLightArr.length) return null;
    return (<>
            {highLightArr.map((item, index) => (
                Number(item) === 0 ? null : (
                    <Badge key={index} item={item} colors={colors[index]}/>
                )))}
        </>

    )
};

export {HighLight};

