import React, {useState} from 'react';

import css from "./Orders.module.css"
import {useDispatch, useSelector} from "react-redux";
import {ButtonNewOrder} from "../ButtonNewOrder/ButtonNewOrder";
import {Modal} from "../Modal/Modal";
import {TreeViewOrder} from "../TreeViewContainer/TreeViewOrder";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {EditNameDialog} from "../ModalContainer/EditNameDialog";
import {ImportTextOrderDialog} from "../ModalContainer/ImportTextOrderDialog";
import {ProductCard} from "../../ProductCard/ProductCard";
import {NumericKeyboard} from "../NumericKeyboard/NumericKeyboard";

const Orders = () => {
    const dispatch = useDispatch();
    const userRole = useSelector(state => state.data.userRole);
    const treeViewList = useSelector(state => state.data.orders);
    const isModalOpen = useSelector(state => state.data.isModalOpen);

    const [currentItem, setCurrentItem] = useState(null);
    const [importOrder, setImportOrder] = useState(null);

    const closeModal = () => dispatch(dataSourceActions.setIsModalOpen(false));
    const [editOrderQuantity, setEditOrderQuantity] = useState(null)
    const closeModalImportOrder = () => setImportOrder(null)
    const greeting = {
        "manager": <div className={css.greeting}>Зараз у вас немає жодної збереженої інформації.<br/> Кожне нове
            замовлення зберігається за покупцем, тому для початку натисніть
            на кнопку <ButtonNewOrder/> <br/> і введіть назву покупця. Далі покупцю можна додати замовлення. Кожен новий
            покупець додається за допомогаю цієї ж кнопки, шукайте її в шапці</div>,
        "user": <div className={css.greeting}>Зараз у вас немає жодного збереженого замовлення.<br/>Щоб розпочати нове
            замовлення
            натисніть зверху на кнопку <ButtonNewOrder/></div>
    }

    const closeModalEditOrderQuantity=()=>{
        setEditOrderQuantity(null)
    }

    if (!isModalOpen && treeViewList.length === 0) return greeting[userRole];

    return (
        <div className={css.orders}>
            {treeViewList.map(item => <TreeViewOrder key={item.id}
                                                     item={item}
                                                     setCurrentItem={setCurrentItem}
                                                     setImportOrder={setImportOrder}
                                                     setEditOrderQuantity={setEditOrderQuantity}
            />)}

            <Modal active={isModalOpen} setActive={closeModal}>
                <EditNameDialog closeModal={closeModal} currentItem={currentItem} setCurrentItem={setCurrentItem}/>
            </Modal>

            <Modal active={Boolean(importOrder)} setActive={closeModalImportOrder}>
                <ImportTextOrderDialog importOrder={importOrder} setImportOrder={setImportOrder}/>
            </Modal>

            <Modal active={Boolean(editOrderQuantity)} setActive={closeModalEditOrderQuantity}>
                <ProductCard>
                    <NumericKeyboard closeModal={closeModalEditOrderQuantity}/>
                </ProductCard>
            </Modal>

        </div>
    );
};

export {Orders};