import React, {useRef, useState} from 'react';

import css from "./UpdateData.module.css"
import {useLocation, useNavigate} from "react-router-dom";

import {Button} from "../Button/Button";
import {useDispatch, useSelector} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {Loader} from "../Loader/Loader";

const renderElement = (handleDecrypt = () => {
}, handleLater = () => {
}) => {
    return {
        "toLoad": {
            title: "На зараз немає жодної збереженої інформації по залишках. Залишки закодовані, потрібно ввести код. Код можна дізнатися у нашого менеджера або в телеграм боті",
            btn: <Button className={css.btn} onClick={handleDecrypt}>Розкодувати</Button>
        },
        "toRefresh": {
            title: "Доступні більш свіжіші залишки. Для їх оновлення, введіть код",
            btn: <>
                <Button className={css.btn} onClick={handleDecrypt}>Розкодувати</Button>
                <Button className={css.btn} onClick={handleLater}>Не Зараз, Пізніше</Button>
            </>
        }
    }
}

const UpdateData = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const action = location?.state?.actionFreshData;
    // const fromPage = location.state?.from?.pathname || "/update";
    const [secretKey, setSecretKey] = useState("");

    const inputRef = useRef();
    const {isLoading} = useSelector(state => state.data);
    const dispatch = useDispatch();
    const fromPage = location.state?.from?.pathname || "/";

    const handlerChange = (e) => {
        setSecretKey(e.target.value)
    }
    const handleDecrypt = async () => {
        inputRef.current.focus();
        await dispatch(dataSourceActions.setSourceData({secretCode: secretKey}));

        navigate(fromPage, {replace: true});
    }
    const onKeyPressHandler = (e) => {
        if (e.charCode === 13) {
            handleDecrypt().then()
        }
    }
    const handleLater = () => {
        dispatch(dataSourceActions.setHasFreshData(false));
        navigate(fromPage, {replace: true});
    }

    if (isLoading) return (
        <div style={{display: "flex", height: "100vh", alignItems: "center", justifyContent: "center"}}>
            <Loader/>
        </div>);

    return (
        <div className={css.updateData}>

            <div className={css.title}>{renderElement()[action].title || "NOTHINg"}</div>
            <input
                type="text"
                name="code"
                maxLength="16"
                // size="20"
                placeholder="Код для розкодування"
                value={secretKey}
                ref={inputRef}
                onKeyPress={onKeyPressHandler}
                onChange={(e) => handlerChange(e)}
            />

            {renderElement(handleDecrypt, handleLater)[action].btn}
        </div>
    );
};

export {UpdateData};