import React from 'react';
import {useDispatch, useSelector} from "react-redux";
import css from "./TreeView.module.css";
import {WithBorderHover} from "../../hoc/withBorderHover/withBorderHover";
import {ArrowButton, formatNumber, formatPrice} from "./utils.TreeView";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {useNavigate} from "react-router-dom";
import {ButtonGroup} from "./ButtonGroup";
import {TbSum} from "react-icons/tb";
import {appConstants} from "../../constants/appConstants";
import {BiSolidFileImport} from "react-icons/bi";


const TreeViewOrder = ({item, setCurrentItem, setImportOrder,setEditOrderQuantity}) => {
    const navigate = useNavigate();
    const {expandedRows} = useSelector(state => state.data);
    const dispatch = useDispatch();
    const {id, children, date, data, level, name, totalAmount} = item;
    const handleOrderInsert = (item) => {
        const level = +item.level + 1;
        const parentId = item.id;
        dispatch(dataSourceActions.insertNode({level, parentId}));
        dispatch(dataSourceActions.setExpendedRows(id))
    };
    //todo setCurrentItem ?
    const handleOrderEdit = (item) => {

        setCurrentItem(item);
        dispatch(dataSourceActions.setIsModalOpen(true));
    };

    const handleOrderDel = (id) => {
        dispatch(dataSourceActions.deleteNode(id));
        dispatch(dataSourceActions.toggleExpendedRows(id));
    };

    const handleOrderSendToTelegram = (item) => {
        dispatch(dataSourceActions.copyOrderToClipboard(item));
    };
    const handleProductQuantity = (item) => {
        setEditOrderQuantity(item)
        dispatch(dataSourceActions.setSelectedItem({selectedItem:item}))
    }

    const handleRowClick = {
        1: () => handleOpenOrder(item),
        2: () => handleProductQuantity(item),
        0: null
    }
    const handleClickArrow = (id) => {
        dispatch(dataSourceActions.toggleExpendedRows(id));
    };

    const renderChildren = () => {
        return expandedRows.includes(id) && children && (<div className={css.sub_title}>
            {children.map((subitem) => <TreeViewOrder key={subitem.id} item={subitem}
                                                      setCurrentItem={setCurrentItem}
                                                      setImportOrder={setImportOrder}
                                                      setEditOrderQuantity={setEditOrderQuantity}
            />)}
        </div>);
    }
    const renderName = () => {
        return (<div className={css.name}>
            <div>
                {name}</div>
            {date && <div>
                {item?.receive ? <span
                    className={css.receive}><BiSolidFileImport/> {new Date(date).toLocaleString(appConstants.local)}</span> : new Date(date).toLocaleString(appConstants.local)}


                {/*{new Date(date).toLocaleString(appConstants.local)}*/}
            </div>}
            {level === 1 && totalAmount ?
                <div className={css.total_price}><TbSum/>{formatPrice(+totalAmount)}</div> : null}
        </div>)
    }

    const handleOpenOrder = (item) => {
        navigate(`/orders/${item.id}`);
    }

    const handleOrderImport = (item) => {
        setImportOrder(item);
    }
    const renderGroupButton = (item) => {
        return (<div className={css.group_button}>
            {ButtonGroup(item, () => handleOrderInsert(item), () => handleOrderEdit(item), () => handleOrderDel(item.id), () => handleOrderSendToTelegram(item), () => handleOrderImport(item))[level]}
        </div>)
    }

    const renderDataField = (data) => {
        if (!data) return null;
        const {price, unit, quantity, stock} = data
        return (<div className={css.column}>
            <div className={css.price}>{formatNumber(+price)}</div>
            <div className={css.stock}>{formatNumber(+stock, 0)} {unit} </div>
            {quantity && <div className={css.quantity}>{formatNumber(+quantity, 0)}</div>}
        </div>)
    }
    return (<>
        <WithBorderHover>
            <div className={css.row}>
                <ArrowButton isExpanded={expandedRows.includes(id)} handleClick={() => handleClickArrow(id)}
                             item={item}/>
                <div className={data ? css.title : css.group}
                     onClick={handleRowClick[level]}>

                    {/*{item?.receive ? <div className={css.receive}><BiSolidFileImport/></div> : null}*/}
                    {renderName()}

                    {renderDataField(data)}
                    {renderGroupButton(item)}
                </div>
            </div>

            {renderChildren()}

        </WithBorderHover>

    </>);
};

export {
    TreeViewOrder
};