import React, {useEffect} from 'react';

import css from "./ErrorDisplay.module.css"
import {Button} from "../Button/Button";
import {useDispatch, useSelector} from "react-redux";
import {dataSourceActions} from "../../redux/slices/dataSource.slice";
import {appConstants} from "../../constants/appConstants";

import {FaWindowClose} from "react-icons/fa";

const ErrorDisplay = () => {
    const durationShowVisible = appConstants.durationShowVisible;

    const errors = useSelector(state => state.data.errors);
    const dispatch = useDispatch();

    const handleCloseError = () => {
        dispatch(dataSourceActions.setError(null))
    }

    useEffect(() => {
        if (errors) {
            setTimeout(() => {
                dispatch(dataSourceActions.setError(null))
            }, durationShowVisible)
        }

    }, [errors, durationShowVisible, dispatch]);

    return (

            <div className={css.error_display}>
                <div className={errors ? [css.context, css.open].join(" ") : css.context}>
                    <div style={{padding:"0.2em", textAlign:"center", width:"100%"}} >{errors}</div>

                    <FaWindowClose style={{margin:"0.2em"}} onClick={handleCloseError}/>
                </div>
            </div>
    );
};

export {ErrorDisplay};