import React from 'react';

import css from "./NavBar.module.css"
import {NavLink} from "react-router-dom";
import {navBarLinks} from "../../router";


const NavBar = ({children, isOpen}) => {
    const LiElement = ({goTo, title,tgFalseIsVisible}) => {
        return (
            tgFalseIsVisible ?
                <li><NavLink to={goTo}>{title}</NavLink></li>
                : null
        )
    }

    return (
        <div className={isOpen ? [css.navBar, css.nav_active].join(" ") : css.navBar}>
            <nav>
                <ul className={css.nav_list}>
                    {navBarLinks.map(item => <LiElement key={item.goTo} {...item}/>)}
                </ul>
            </nav>
            <div className={css.children}>
                {children}
            </div>

        </div>
    );
};

export {NavBar};