import React from 'react';

import css from "./Badge.module.css"
const Badge = ({item,colors}) => {
    const{bc,c}=colors;
    if(Number(item)===0) return null;
    return (
        <div className={css.badge} style={{background:`${bc}`, color:`${c}`}}>
            {item}
        </div>
    );
};

export  {Badge};